import {scenario as C} from './scenario.js';import {initialState,reduce,available,has} from './economy.js';import {createCity} from './city.js';
let state=initialState(),screen='welcome',destination='market',returnScreen='hub',item='decal',travelTimer;const el=id=>document.getElementById(id);let city;
try{city=createCity(el('world'));}catch(e){console.error(e);el('world').textContent='3D view unavailable. The complete budget prototype still works below.';}
const button=(label,action,value='',kind='')=>`<button class="${kind}" data-action="${action}" data-value="${value}">${label}</button>`;
const actions=(...items)=>`<div class="actions">${items.join('')}</div>`;
const info=(value,warning=false)=>`<div class="info ${warning?'warning':''}">${value}</div>`;
const list=rows=>`<div class="budget-list">${rows.map(([l,v])=>`<div><span>${l}</span><b>${v}</b></div>`).join('')}</div>`;
function frame(tag,title,body){return `<p class="eyebrow">${tag}</p><h2>${title}</h2>${body}`;}
function dispatch(type,value){state=reduce(state,{type,value});if(state.notice)notice(state.notice);city?.update(state);}
function notice(t){el('notice').textContent=t;clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>el('notice').textContent='',4500);}
function go(next){clearTimeout(travelTimer);screen=next;render();el('panel').scrollTop=0;}
function render(){for(const id of ['cash','bills','groceries','goal','coins','gems'])el(id).textContent=state[id];el('available').textContent=available(state);el('world-stage').textContent=state.equipped?'PERSONALIZED / YOUR EXPRESSION':state.rewarded?'CONNECTED / LEARNING MILESTONE':'FOUNDATION / CHAPTER 01';const b=C.baskets.find(b=>b.id===state.basket),a=available(state);let html='';
 switch(screen){
 case 'welcome':html=frame('CHAPTER 01 · A FICTIONAL SIMULATION','Make room for what matters.',`<p class="sub">Explore the neighborhood, plan a week and handle a surprise. Start with something you want to save for.</p>${C.goals.map(g=>`<button class="choice ${state.selectedGoal===g?'selected':''}" data-action="choose-goal" data-value="${g}" aria-pressed="${state.selectedGoal===g}"><strong>${g}</strong><small>A personal goal, at your own pace.</small></button>`).join('')}${actions(button('Plan my week →','go','plan','primary'))}<p class="hint">About 5 minutes · No real money · You can reset and try again.</p>`);break;
 case 'plan':html=frame('YOUR WEEK · YOUR PLAN','500 in cash. A plan for all of it.',`<p class="sub">You’re saving for a ${state.selectedGoal.toLowerCase()}. Set aside essentials first.</p>${list([['Cash balance',state.cash],['Unpaid bills reserved',state.bills],['Groceries reserved',state.groceries],[state.selectedGoal+' reserved',state.goal],['Available to spend',a]])}${info('Reserves are part of your cash, not extra money or charges. Available = cash minus all reserves.')}${actions(button('Choose goal','go','welcome'),button('Explore the city →','go','hub','primary'))}`);break;
 case 'hub':{const done=has(state,'repair');html=frame('YOUR NEIGHBORHOOD',done?'A little wiser. Still your city.':'Where to next?',`<p class="sub">${done?'Your weekly decisions are complete. Explore your rewards or replay the outcome.':has(state,'utility')?'The garage has an unexpected update.':has(state,'grocery')?'Groceries sorted. Your utility bill is next.':'The market has two ways to fill your basket.'}</p>${button(`${has(state,'grocery')?'✓':'01'} Market · ${has(state,'grocery')?'Purchase complete':'Compare groceries'}`,'visit','market','choice')}${button(`${has(state,'utility')?'✓':'02'} Utilities · ${has(state,'utility')?'120 paid':'Bill of 120'}`,'visit','utility','choice')}${has(state,'utility')?button(`${done?'✓':'03'} Garage · ${done?'Repair complete':'Review a surprise'}`,'go',done?'outcome':'repair','choice'):''}${actions(button('Cosmetic store','open-store'),button('Hire help demo','open-help'))}${done?actions(button('Review my week','go','outcome','primary')):info('Learning opens new activities. Buying cosmetics never solves a budget.')}<p class="hint">Bank district: opens in a later chapter. This first slice covers one neighborhood.</p>`);break;}
 case 'preview':html=frame('DESTINATION PREVIEW',destination==='market'?'The corner market':'Utility service center',`<p class="sub">${destination==='market'?'Compare two complete baskets. Both cover the household’s needs; preparation and convenience differ.':'Understand the amount, usage and due date before paying from your bill reserve.'}</p>${list(destination==='market'?[['Expected basket','60–80'],['Grocery reserve','80'],['Visit','About 1 minute']]:[['Bill amount','120'],['Reserved for bills',state.bills],['Due','End of simulated week']])}${actions(button('Stay here','go','hub'),button('Travel →','travel','','primary'))}`);break;
 case 'travel':html=frame('ON YOUR WAY',destination==='market'?'Next stop: the market.':'Next stop: utilities.',`<p class="sub">A short trip across the neighborhood. Travel doesn’t cost cash in this demo.</p><div class="progress"><span style="width:65%"></span></div>${actions(button('Skip journey →','arrive','','primary'),button('Return to city','go','hub'))}`);break;
 case 'groceries':html=frame('MARKET · COMPARE VALUE','Two baskets. One decision.',`<p class="sub">Both cover four packs each of grains, protein and produce. Choose how you balance price and convenience.</p>${C.baskets.map(x=>`<button class="choice ${state.basket===x.id?'selected':''}" data-action="select-basket" data-value="${x.id}"><span class="price">${x.cost}</span><strong>${x.name}</strong><small>${x.description}</small></button>`).join('')}${info(state.basket?`After buying: ${state.cash-b.cost} cash · ${a+state.groceries-b.cost} available. Your entire grocery reserve is released.`:'Select a complete basket to see its effect. Nothing is charged until confirmation.')}${actions(button('Back to city','go','hub'),button('Review basket →','review','','primary'))}<p class="hint">Illustrative quantities and prices; curriculum review pending.</p>`);break;
 case 'review':html=frame('MARKET · PURCHASE REVIEW',b?.name||'Choose a basket',`${b?list([...b.lines,['Basket total',b.cost],['Cash after purchase',state.cash-b.cost],['Available after purchase',a+state.groceries-b.cost]]):''}${info('This purchase releases the 80 grocery reserve. Bills and your goal remain protected.')}${actions(button('Edit basket','go','groceries'),button('Confirm purchase','buy-grocery','','primary'))}`);break;
 case 'grocery-done':html=frame('GROCERIES · COMPLETE','Your basket is paid for.',`${list([['Basket',b?.cost||'—'],['Cash now',state.cash],['Grocery reserve',0],['Available now',a]])}${info('This transaction is already recorded. Returning here does not charge you again.')}${actions(button('Return to city →','go','hub','primary'))}`);break;
 case 'utility':html=frame('UTILITIES · BILL REVIEW','Keep the lights on.',`<p class="sub">Electricity for the simulated household. Due at the end of this week.</p>${list([['Usage · 100 units × 1',100],['Service charge',20],['Total due',120],['Cash after payment',state.cash-120],['Bills still reserved',state.bills-120],['Available after payment',a]])}${info('Paying a reserved bill reduces cash and the bill reserve equally. Available cash stays the same.')}${actions(button('Back to city','go','hub'),button('Pay 120','pay-utility','','primary'))}`);break;
 case 'utility-done':html=frame('UTILITIES · PAYMENT COMPLETE','One commitment taken care of.',`${list([['Utility paid',120],['Cash now',state.cash],['Unpaid bills still reserved',state.bills],['Available now',a]])}${actions(button('Return to city','go','hub'),button('Garage update →','go','repair','primary'))}`);break;
 case 'repair':html=frame('GARAGE · UNEXPECTED EXPENSE','A repair wasn’t in the plan.',`<p class="sub">The simulation’s car needs a repair. The quote is 90. Review your options before paying.</p>${list([['Repair quote',90],['Available now',a],['Shortfall',Math.max(0,90-a)]])}${info(a<90?'You need 20 more available cash. Nothing has been charged. You can revise your goal allocation.':'Your available cash covers this repair. The bill reserve and your goal stay protected.',a<90)}${actions(button('Back to city','go','hub'),a<90?button('Adjust my plan →','go','adjust','primary'):button('Confirm repair · 90','pay-repair','','primary'))}`);break;
 case 'adjust':html=frame('ADAPT YOUR PLAN','A different pace. The same goal.',`<p class="sub">Keep essentials protected and reserve 30 for your ${state.selectedGoal.toLowerCase()} this week.</p>${list([['Goal reserve',`${state.goal} → 30`],['Cash balance',`${state.cash} → ${state.cash}`],['Available after adjustment',state.cash-state.bills-state.groceries-30],['Available after repair',state.cash-state.bills-state.groceries-30-90]])}${info('Moving 20 out of the goal allocation changes your plan, not your cash balance. Revising a plan is a useful skill.')}${actions(button('Keep current plan','go','repair'),button('Use revised plan','revise-goal','','primary'))}`);break;
 case 'outcome':html=frame('YOUR WEEK · OUTCOME','You made a plan. Then adapted.',`<div class="ledger">${state.transactions.map(t=>`<div><span>${t.label}</span><b>−${t.amount}</b></div>`).join('')}</div>${list([['Cash remaining',state.cash],['Unpaid bills still reserved',state.bills],['Goal reserve',state.goal],['Available to spend',a]])}${info(state.goal===50?'Your lower-cost basket left room for the repair while preserving your goal.':'Your convenience choice meant reserving 20 less for your goal. You adjusted before spending protected money.')}${actions(button('Back to city','go','hub'),button(state.rewarded?'See my milestone':'Reflect & continue →','go','reward','primary'))}`);break;
 case 'reward':html=frame('LEARNING MILESTONE','Planning is a skill you can grow.',`<p class="sub">You separated commitments from spendable cash, compared options and handled a surprise.</p><div class="reward"><div><b>100</b>Style Coins</div><div><b>5</b>Gems</div></div>${info('A community activity opens in your neighborhood. This celebrates the chapter; one household payment did not fund city infrastructure.')}<p class="hint">This curated demo illustrates learning. It does not establish validated mastery.</p>${actions(button(state.rewarded?'Return to my city →':'Collect once & return →',state.rewarded?'go':'claim',state.rewarded?'hub':'','primary'))}`);break;
 case 'store':html=frame('STYLE STUDIO · COSMETICS','Make it feel like yours.',`<p class="sub">Cosmetics use their own currencies. Household cash is never spent here.</p>${C.items.map(i=>button(`<strong>${i.name}</strong><small>${i.price} ${i.currency==='coins'?'Style Coins':'Gems'} · ${state.equipped===i.id?'Equipped':state.owned.includes(i.id)?'Owned':state[i.currency]>=i.price?'Affordable':'Not enough currency'}</small>`,'item',i.id,'choice')).join('')}${info('Neighborhood mural · learning-locked until a later chapter. Gems cannot unlock lesson answers or mastery.')}${actions(button('Return to city','go','hub'))}`);break;
 case 'item':{const i=C.items.find(x=>x.id===item),owned=state.owned.includes(item),equipped=state.equipped===item,can=state[i.currency]>=i.price;html=frame('STYLE STUDIO · ITEM PREVIEW',i.name,`<p class="sub">${item==='decal'?'A warm cream stripe for your car. Your budget and learning progress stay unchanged.':'Deep blue body paint. Preview only until you have enough Gems.'}</p><div style="height:75px;background:${item==='decal'?'linear-gradient(0deg,#d6a55c 42%,#eee1bd 42%,#eee1bd 58%,#d6a55c 58%)':'#334b68'};border-radius:12px;margin:20px 0" aria-label="${i.name} color and pattern preview"></div>${list([['Price',i.price+' '+(i.currency==='coins'?'Style Coins':'Gems')],['Your balance',state[i.currency]],['Balance after purchase',owned?'Already owned':can?state[i.currency]-i.price:'Purchase unavailable']])}${!owned&&!can?info(`You need ${i.price-state[i.currency]} more ${i.currency==='coins'?'Style Coins':'Gems'}. No real-money checkout is part of this prototype.`,true):''}${actions(button('Cancel / store','go','store'),owned?button(equipped?'Unequip':'Equip on my car',equipped?'unequip':'equip',item,'primary'):can?button('Confirm purchase','buy-item',item,'primary'):'')}`);break;}
 case 'help':html=frame('SEPARATE EXAMPLE · RESETTABLE','Pay for time. Keep the decision.',`<p class="sub">Try a separate household example: 110 cash, with 80 protected for groceries and 30 available. Your main week stays unchanged.</p>${list([['Available in this example',state.helper.cash-state.helper.groceries],['Delivery helper fee',10],['Time slots',2],['Delivery saves','1 slot'],['Available after hire',state.helper.cash-state.helper.groceries-10]])}${info('One session, no automatic renewal. Cancel before delivery for a full 10 refund. The helper does not choose your basket or answer the lesson.')}${actions(button('Back to city','go','hub'),button(state.helper.status==='active'?'View active help':'Hire for 10',state.helper.status==='active'?'go':'hire',state.helper.status==='active'?'help-active':'','primary'))}${actions(button('Self-shop · no helper fee','go','self-shop'),button('Reset this example','reset-help'))}`);break;
 case 'self-shop':html=frame('SEPARATE EXAMPLE · SELF-SERVICE','Your time, your choice.',`${list([['Helper fee',0],['Time used','1 of 2 slots'],['Time remaining','1 slot'],['Available cash',state.helper.cash-state.helper.groceries],['Groceries still reserved',80]])}${info('Groceries still need to be paid for. This example compares only the helper fee and time; it does not charge a grocery basket.')}${actions(button('Compare delivery','go','help'),button('Return to city','go','hub','primary'))}`);break;
 case 'help-active':html=frame('SEPARATE EXAMPLE · ACTIVE HELP','One delivery. More time.',`${list([['Example cash',state.helper.cash],['Groceries still reserved',80],['Available in example',state.helper.cash-80],['Time slots retained',2],['Next charge','None']])}${info('Delivery has not started. Cancellation returns the 10 fee once.')}${actions(button('Cancel help','go','help-cancel'),button('Return to city','go','hub','primary'))}`);break;
 case 'help-cancel':html=frame('SEPARATE EXAMPLE · CANCELLATION','Cancel this delivery?',`${list([['Refund',10],['Example cash after refund',state.helper.cash+10],['Available after refund',state.helper.cash+10-80],['Future charges','None']])}${actions(button('Keep delivery','go','help-active'),button('Confirm cancellation','cancel-help','','primary'))}`);break;
 default:html=frame('RECOVERY','Let’s head back.',actions(button('Return to city','go','hub','primary')));
 }el('panel').innerHTML=html;}
el('panel').addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,value}=target.dataset;
 switch(action){case 'go':go(value);break;case 'choose-goal':dispatch('goal',value);render();break;case 'visit':destination=value;if(value==='utility'&&!has(state,'grocery')){notice('Start with the market. Your bill reserve is protected.');return;}go(has(state,value==='market'?'grocery':'utility')?(value==='market'?'grocery-done':'utility-done'):'preview');break;case 'travel':go('travel');city?.travel(el('motion').checked);travelTimer=setTimeout(()=>go(destination==='market'?'groceries':'utility'),el('motion').checked?250:2300);break;case 'arrive':go(destination==='market'?'groceries':'utility');break;case 'select-basket':dispatch('basket',value);render();break;case 'review':if(!state.basket){notice('Choose a basket first. Nothing has been charged.');return;}go('review');break;case 'buy-grocery':dispatch(action);go(state.notice?'groceries':'grocery-done');break;case 'pay-utility':dispatch(action);go(state.notice?'utility':'utility-done');break;case 'revise-goal':dispatch(action);go('repair');break;case 'pay-repair':dispatch(action);go(state.notice?'repair':'outcome');break;case 'claim':dispatch('claim-reward');go('hub');notice('Milestone collected once. Your neighborhood is now Connected.');break;case 'open-store':go('store');break;case 'item':item=value;go('item');break;case 'buy-item':dispatch(action,value);render();break;case 'equip':dispatch(action,value);go('hub');break;case 'unequip':dispatch(action);render();break;case 'open-help':go(state.helper.status==='active'?'help-active':'help');break;case 'hire':dispatch(action);go('help-active');break;case 'cancel-help':dispatch(action);go('help');notice('Delivery canceled. The 10 fee was refunded once.');break;case 'reset-help':dispatch(action);go('help');break;}
});
el('settings').onclick=()=>el('settings-dialog').showModal();el('close-settings').onclick=()=>el('settings-dialog').close();el('large-text').onchange=e=>document.body.classList.toggle('large-text',e.target.checked);el('motion').checked=matchMedia('(prefers-reduced-motion: reduce)').matches;el('reset').onclick=()=>{el('settings-dialog').close();el('reset-dialog').showModal();};el('cancel-reset').onclick=()=>el('reset-dialog').close();el('confirm-reset').onclick=()=>{dispatch('reset');go('welcome');city?.reset();el('reset-dialog').close();};el('camera').onclick=()=>city?.reset();render();
